+import { zodResolver } from "@hookform/resolvers/zod";
+import { useForm } from "react-hook-form";
+import { z } from "zod";
+import { Button } from "@/components/ui/button";
+import { Input } from "@/components/ui/input";
+import { Label } from "@/components/ui/label";
+import { Textarea } from "@/components/ui/textarea";
+import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
+import { ClientComplaintCreate } from "@/types/crm";
+
+const clientComplaintSchema = z.object({
+  complaint_id: z.string().min(1, "Complaint ID is required"),
+  date_raised: z.string().min(1, "Date Raised is required"),
+  client_id: z.string().min(1, "Client ID is required"),
+  reference_type: z.string().min(1, "Reference Type is required"),
+  reference_id: z.string().optional(),
+  complaint_type: z.string().min(1, "Complaint Type is required"),
+  severity: z.string().min(1, "Severity is required"),
+  description: z.string().optional(),
+  root_cause: z.string().optional(),
+  status: z.string().default("Open"),
+  owner_id: z.string().optional(),
+  closure_date: z.string().optional(),
+  notes: z.string().optional(),
+});
+
+type ClientComplaintFormData = z.infer<typeof clientComplaintSchema>;
+
+interface ClientComplaintFormProps {
+  initialData?: Partial<ClientComplaintCreate>;
+  onSubmit: (data: ClientComplaintCreate) => Promise<void>;
+  onCancel?: () => void;
+  isLoading?: boolean;
+}
+
+export function ClientComplaintForm({
+  initialData,
+  onSubmit,
+  onCancel,
+  isLoading,
+}: ClientComplaintFormProps) {
+  const form = useForm<ClientComplaintFormData>({
+    resolver: zodResolver(clientComplaintSchema),
+    defaultValues: {
+      complaint_id: initialData?.complaint_id ?? "",
+      date_raised: initialData?.date_raised ?? "",
+      client_id: initialData?.client_id ?? "",
+      reference_type: initialData?.reference_type ?? "",
+      reference_id: initialData?.reference_id ?? "",
+      complaint_type: initialData?.complaint_type ?? "",
+      severity: initialData?.severity ?? "",
+      description: initialData?.description ?? "",
+      root_cause: initialData?.root_cause ?? "",
+      status: initialData?.status ?? "Open",
+      owner_id: initialData?.owner_id ?? "",
+      closure_date: initialData?.closure_date ?? "",
+      notes: initialData?.notes ?? "",
+    },
+  });
+
+  const handleSubmit = async (data: ClientComplaintFormData) => {
+    await onSubmit(data as ClientComplaintCreate);
+  };
+
+  const fields = [
+    { name: "complaint_id", label: "Complaint ID", type: "text" },
+    { name: "date_raised", label: "Date Raised", type: "date" },
+    { name: "client_id", label: "Client ID", type: "text" },
+    { name: "reference_type", label: "Reference Type", type: "text" },
+    { name: "reference_id", label: "Reference ID", type: "text" },
+    { name: "complaint_type", label: "Complaint Type", type: "text" },
+    { name: "severity", label: "Severity", type: "text" },
+    { name: "description", label: "Description", type: "text" },
+    { name: "root_cause", label: "Root Cause", type: "text" },
+    { name: "status", label: "Status", type: "text" },
+    { name: "owner_id", label: "Owner ID", type: "text" },
+    { name: "closure_date", label: "Closure Date", type: "date" },
+  ];
+
+  return (
+    <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-6">
+      <Card>
+        <CardHeader>
+          <CardTitle>Create Client Complaint</CardTitle>
+        </CardHeader>
+        <CardContent className="space-y-4">
+          {fields.map((field) => (
+            <div key={field.name} className="space-y-2">
+              <Label htmlFor={field.name}>{field.label}</Label>
+              <Input
+                id={field.name}
+                type={field.type}
+                {...form.register(field.name as never)}
+              />
+              {form.formState.errors[field.name as keyof typeof form.formState.errors] && (
+                <p className="text-sm text-red-500">
+                  {(
+                    form.formState.errors[field.name as keyof typeof form.formState.errors] as {
+                      message: string;
+                    }
+                  ).message}
+                </p>
+              )}
+            </div>
+          ))}
+
+          <div className="space-y-2">
+            <Label htmlFor="notes">Notes</Label>
+            <Textarea id="notes" {...form.register("notes")} />
+          </div>
+        </CardContent>
+      </Card>
+
+      <div className="flex gap-3 justify-end">
+        {onCancel && (
+          <Button type="button" variant="outline" onClick={onCancel}>
+            Cancel
+          </Button>
+        )}
+        <Button type="submit" disabled={isLoading}>
+          {isLoading ? "Saving..." : "Save"}
+        </Button>
+      </div>
+    </form>
+  );
+}
