+      <CardContent>
+        {isLoading ? (
+          <Skeleton className="h-20 w-full" />
+        ) : (
+          <div className="space-y-4">
+            <div className="text-center">
+              <span className="text-3xl font-bold text-purple-400">{stats.inProgress}</span>
+              <p className="text-sm text-slate-500 mt-1">In Progress</p>
+            </div>
+            <div className="text-center">
+              <span className="text-3xl font-bold text-orange-400">{stats.closed}</span>
+              <p className="text-sm text-slate-500 mt-1">Closed</p>
+            </div>
+          </div>
+        )}
+      </CardContent>
+    </Card>
+  );
+}

