import { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { marketingApi as api, type Metric } from "@/lib/marketingApi";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { ArrowLeft, ArrowRight, Search } from "lucide-react";
import { MetricType } from "@/types/marketing";

interface MetricListProps {
  metricType: MetricType;
  metricTypeLabel: string;
  listKey: string;
}

export function MetricList({ metricType, metricTypeLabel, listKey }: MetricListProps) {
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  const pageSize = 20;

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedSearch(search), 300);
    return () => clearTimeout(timer);
  }, [search]);

  const { data, isLoading } = useQuery({
    queryKey: [listKey, page, debouncedSearch],
    queryFn: () => api.listMetrics(metricType, { page, page_size: pageSize, q: debouncedSearch }),
  });

  const metrics = data?.items ?? [];
  const total = data?.total ?? 0;
  const totalPages = Math.ceil(total / pageSize);

  const getColumns = () => {
    switch (metricType) {
      case "instagram":
        return [
          { key: "metric_id", label: "Metric ID" },
          { key: "period_yyyymm", label: "Period (YYYYMM)" },
          { key: "followers_start", label: "Followers Start" },
          { key: "followers_end", label: "Followers End" },
          { key: "followers_net_add", label: "Net Add" },
          { key: "impressions", label: "Impressions" },
          { key: "reach", label: "Reach" },
          { key: "profile_visits", label: "Profile Visits" },
          { key: "likes", label: "Likes" },
          { key: "comments", label: "Comments" },
        ];
      case "linkedin":
        return [
          { key: "metric_id", label: "Metric ID" },
          { key: "period_yyyymm", label: "Period (YYYYMM)" },
          { key: "followers_start", label: "Followers Start" },
          { key: "followers_end", label: "Followers End" },
          { key: "followers_net_add", label: "Net Add" },
          { key: "impressions", label: "Impressions" },
          { key: "reach", label: "Reach" },
          { key: "profile_views", label: "Profile Views" },
          { key: "reactions", label: "Reactions" },
          { key: "comments", label: "Comments" },
        ];
      case "website":
        return [
          { key: "metric_id", label: "Metric ID" },
          { key: "period_yyyymm", label: "Period (YYYYMM)" },
          { key: "sessions", label: "Sessions" },
          { key: "users", label: "Users" },
          { key: "page_views", label: "Page Views" },
          { key: "bounce_rate", label: "Bounce Rate" },
          { key: "contact_form_submissions", label: "Contact Forms" },
          { key: "consultation_requests", label: "Consultations" },
          { key: "leads_count", label: "Leads" },
          { key: "inquiry_count", label: "Inquiries" },
        ];
      default:
        return [];
    }
  };

  const columns = getColumns();

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold">{metricTypeLabel}</h1>
        <Button asChild>
          <Link to={`/${metricType}/new`}>New {metricTypeLabel} Metric</Link>
        </Button>
      </div>

      <Card>
        <CardContent className="pt-6">
          <div className="relative mb-4">
            <Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder={`Search ${metricTypeLabel.toLowerCase()}...`}
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-10"
            />
          </div>

          <div className="rounded-md border">
            <Table>
              <TableHeader>
                <TableRow>
                  {columns.map((col) => (
                    <TableHead key={col.key}>{col.label}</TableHead>
                  ))}
                  <TableHead>Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {isLoading ? (
                  <TableRow>
                    <TableCell colSpan={columns.length + 1} className="text-center">Loading...</TableCell>
                  </TableRow>
                ) : metrics.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={columns.length + 1} className="text-center">No metrics found</TableCell>
                  </TableRow>
                ) : (
                  metrics.map((metric: Metric) => (
                    <TableRow key={metric.id}>
                      {columns.map((col) => (
                        <TableCell key={col.key}>{String(metric[col.key as keyof typeof metric] || "-")}</TableCell>
                      ))}
                      <TableCell>
                        <Button variant="ghost" asChild>
                          <Link to={`/${metricType}/${metric.id}`}>View</Link>
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </div>

          <div className="flex items-center justify-between mt-4">
            <span className="text-sm text-muted-foreground">
              {total} metric{total !== 1 ? "s" : ""}
            </span>
            <div className="flex items-center gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => setPage((p) => Math.max(1, p - 1))}
                disabled={page === 1}
              >
                <ArrowLeft className="h-4 w-4" />
              </Button>
              <span className="text-sm">Page {page} of {totalPages}</span>
              <Button
                variant="outline"
                size="sm"
                onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                disabled={page >= totalPages}
              >
                <ArrowRight className="h-4 w-4" />
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

