import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";
import { z } from "zod";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { MetricType } from "@/types/marketing";

const instagramMetricSchema = z.object({
  metric_id: z.string().min(1, "Metric ID is required"),
  period_yyyymm: z.string().min(6, "Period (YYYYMM) is required"),
  followers_start: z.number().min(0),
  followers_end: z.number().min(0),
  followers_net_add: z.number().min(0).optional(),
  impressions: z.number().min(0),
  reach: z.number().min(0),
  profile_visits: z.number().min(0),
  likes: z.number().min(0),
  comments: z.number().min(0),
  shares: z.number().min(0),
  saves: z.number().min(0),
  engagement_rate: z.number().min(0).max(1),
  posts_count: z.number().min(0),
  reels_count: z.number().min(0),
  stories_count: z.number().min(0),
  website_clicks: z.number().min(0),
  inbound_dms: z.number().min(0),
  leads_count: z.number().min(0),
  inquiry_count: z.number().min(0),
  notes: z.string().optional(),
});

const linkedinMetricSchema = z.object({
  metric_id: z.string().min(1, "Metric ID is required"),
  period_yyyymm: z.string().min(6, "Period (YYYYMM) is required"),
  followers_start: z.number().min(0),
  followers_end: z.number().min(0),
  followers_net_add: z.number().min(0).optional(),
  impressions: z.number().min(0),
  reach: z.number().min(0),
  profile_views: z.number().min(0),
  reactions: z.number().min(0),
  comments: z.number().min(0),
  reposts: z.number().min(0),
  engagement_rate: z.number().min(0).max(1),
  posts_count: z.number().min(0),
  articles_count: z.number().min(0),
  videos_count: z.number().min(0),
  website_clicks: z.number().min(0),
  inbound_dms: z.number().min(0),
  leads_count: z.number().min(0),
  inquiry_count: z.number().min(0),
  notes: z.string().optional(),
});

const websiteMetricSchema = z.object({
  metric_id: z.string().min(1, "Metric ID is required"),
  period_yyyymm: z.string().min(6, "Period (YYYYMM) is required"),
  sessions: z.number().min(0),
  users: z.number().min(0),
  new_users: z.number().min(0),
  returning_users: z.number().min(0),
  page_views: z.number().min(0),
  pages_per_session: z.number().min(0),
  avg_session_duration_sec: z.number().min(0),
  bounce_rate: z.number().min(0).max(1),
  direct_traffic_pct: z.number().min(0).max(1),
  organic_traffic_pct: z.number().min(0).max(1),
  social_traffic_pct: z.number().min(0).max(1),
  referral_traffic_pct: z.number().min(0).max(1),
  paid_traffic_pct: z.number().min(0).max(1),
  contact_form_submissions: z.number().min(0),
  consultation_requests: z.number().min(0),
  downloads_count: z.number().min(0),
  call_clicks: z.number().min(0),
  leads_count: z.number().min(0),
  inquiry_count: z.number().min(0),
  projects_converted: z.number().min(0),
  notes: z.string().optional(),
});

type InstagramFormData = z.infer<typeof instagramMetricSchema>;
type LinkedInFormData = z.infer<typeof linkedinMetricSchema>;
type WebsiteFormData = z.infer<typeof websiteMetricSchema>;

interface MetricFormProps {
  metricType: MetricType;
  initialData?: Partial<InstagramFormData | LinkedInFormData | WebsiteFormData>;
  onSubmit: (data: InstagramFormData | LinkedInFormData | WebsiteFormData) => Promise<void>;
  onCancel?: () => void;
  isLoading?: boolean;
}

export function MetricForm({ metricType, initialData, onSubmit, onCancel, isLoading }: MetricFormProps) {
  const getSchema = () => {
    switch (metricType) {
      case "instagram": return instagramMetricSchema;
      case "linkedin": return linkedinMetricSchema;
      case "website": return websiteMetricSchema;
      default: return instagramMetricSchema;
    }
  };

  const form = useForm<InstagramFormData | LinkedInFormData | WebsiteFormData>({
    resolver: zodResolver(getSchema()),
    defaultValues: initialData,
  });

  const handleSubmit = async (data: InstagramFormData | LinkedInFormData | WebsiteFormData) => {
    await onSubmit(data);
  };

  const getFields = () => {
    switch (metricType) {
      case "instagram":
        return [
          { name: "metric_id", label: "Metric ID", type: "text" },
          { name: "period_yyyymm", label: "Period (YYYYMM)", type: "text" },
          { name: "followers_start", label: "Followers Start", type: "number" },
          { name: "followers_end", label: "Followers End", type: "number" },
          { name: "followers_net_add", label: "Net Add", type: "number" },
          { name: "impressions", label: "Impressions", type: "number" },
          { name: "reach", label: "Reach", type: "number" },
          { name: "profile_visits", label: "Profile Visits", type: "number" },
