import { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { crmApi as api, type ClientFeedback } from "@/lib/crmApi";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { ArrowLeft, ArrowRight, Search } from "lucide-react";

interface ClientFeedbackListProps {
  listKey?: string;
}

export function ClientFeedbackList({ listKey = "client-feedback" }: ClientFeedbackListProps) {
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  const pageSize = 20;

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedSearch(search), 300);
    return () => clearTimeout(timer);
  }, [search]);

  const { data, isLoading } = useQuery({
    queryKey: [listKey, page, debouncedSearch],
    queryFn: () => api.listClientFeedback({ page, page_size: pageSize, q: debouncedSearch }),
  });

  const feedback = data?.items ?? [];
  const total = data?.total ?? 0;
  const totalPages = Math.ceil(total / pageSize);

  const columns = [
    { key: "feedback_id", label: "Feedback ID" },
    { key: "date", label: "Date" },
    { key: "client_id", label: "Client ID" },
    { key: "reference_type", label: "Reference Type" },
    { key: "overall_rating", label: "Overall Rating" },
    { key: "quality_rating", label: "Quality Rating" },
    { key: "timeliness_rating", label: "Timeliness Rating" },
    { key: "communication_rating", label: "Communication Rating" },
    { key: "would_recommend", label: "Would Recommend" },
  ];

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold">Client Feedback</h1>
        <Button asChild>
          <Link to="/crm/feedback/new">New Client Feedback</Link>
        </Button>
      </div>

      <Card>
        <CardContent className="pt-6">
          <div className="relative mb-4">
            <Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Search client feedback..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-10"
            />
          </div>

          <div className="rounded-md border">
            <Table>
              <TableHeader>
                <TableRow>
                  {columns.map((col) => (
                    <TableHead key={col.key}>{col.label}</TableHead>
                  ))}
                  <TableHead>Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {isLoading ? (
                  <TableRow>
                    <TableCell colSpan={columns.length + 1} className="text-center">Loading...</TableCell>
                  </TableRow>
                ) : feedback.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={columns.length + 1} className="text-center">No feedback found</TableCell>
                  </TableRow>
                ) : (
                  feedback.map((item: ClientFeedback) => (
                    <TableRow key={item.id}>
                      {columns.map((col) => (
                        <TableCell key={col.key}>
                          {col.key === "would_recommend"
                            ? item.would_recommend ? "Yes" : "No"
                            : String(item[col.key as keyof ClientFeedback] ?? "-")}
                        </TableCell>
                      ))}
                      <TableCell>
                        <Button variant="ghost" asChild>
                          <Link to={`/crm/feedback/${item.id}`}>View</Link>
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </div>

          <div className="flex items-center justify-between mt-4">
            <span className="text-sm text-muted-foreground">
              {total} feedback{total !== 1 ? "s" : ""}
            </span>
            <div className="flex items-center gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => setPage((p) => Math.max(1, p - 1))}
                disabled={page === 1}
              >
                <ArrowLeft className="h-4 w-4" />
              </Button>
              <span className="text-sm">Page {page} of {totalPages}</span>
              <Button
                variant="outline"
                size="sm"
                onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                disabled={page >= totalPages}
              >
                <ArrowRight className="h-4 w-4" />
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";
import { z } from "zod";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { ClientFeedbackCreate } from "@/types/crm";

const clientFeedbackSchema = z.object({
  feedback_id: z.string().min(1, "Feedback ID is required"),
  date: z.string().min(1, "Date is required"),
  client_id: z.string().min(1, "Client ID is required"),
  reference_type: z.string().min(1, "Reference Type is required"),
  reference_id: z.string().optional(),
  overall_rating: z.number().min(1).max(5),
  quality_rating: z.number().min(1).max(5),
  timeliness_rating: z.number().min(1).max(5),
  communication_rating: z.number().min(1).max(5),
  would_recommend: z.boolean(),
  comments: z.string().optional(),
});

type ClientFeedbackFormData = z.infer<typeof clientFeedbackSchema>;

interface ClientFeedbackFormProps {
  initialData?: Partial<ClientFeedbackCreate>;
  onSubmit: (data: ClientFeedbackCreate) => Promise<void>;
  onCancel?: () => void;
  isLoading?: boolean;
}

export function ClientFeedbackForm({
  initialData,
  onSubmit,
  onCancel,
  isLoading,
}: ClientFeedbackFormProps) {
  const form = useForm<ClientFeedbackFormData>({
    resolver: zodResolver(clientFeedbackSchema),
    defaultValues: {
      feedback_id: initialData?.feedback_id ?? "",
      date: initialData?.date ?? "",
      client_id: initialData?.client_id ?? "",
      reference_type: initialData?.reference_type ?? "",
      reference_id: initialData?.reference_id ?? "",
      overall_rating: initialData?.overall_rating ?? 3,
      quality_rating: initialData?.quality_rating ?? 3,
      timeliness_rating: initialData?.timeliness_rating ?? 3,
      communication_rating: initialData?.communication_rating ?? 3,
      would_recommend: initialData?.would_recommend ?? false,
      comments: initialData?.comments ?? "",
    },
  });

  const handleSubmit = async (data: ClientFeedbackFormData) => {
    await onSubmit(data as ClientFeedbackCreate);
  };

  const fields = [
    { name: "feedback_id", label: "Feedback ID", type: "text" },
    { name: "date", label: "Date", type: "date" },
    { name: "client_id", label: "Client ID", type: "text" },
    { name: "reference_type", label: "Reference Type", type: "text" },
    { name: "reference_id", label: "Reference ID", type: "text" },
    { name: "overall_rating", label: "Overall Rating (1-5)", type: "number" },
    { name: "quality_rating", label: "Quality Rating (1-5)", type: "number" },
    { name: "timeliness_rating", label: "Timeliness Rating (1-5)", type: "number" },
    { name: "communication_rating", label: "Communication Rating (1-5)", type: "number" },
  ];

  return (
    <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Create Client Feedback</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {fields.map((field) => (
            <div key={field.name} className="space-y-2">
              <Label htmlFor={field.name}>{field.label}</Label>
              <Input
                id={field.name}
                type={field.type}
                {...form.register(field.name as never, {
                  valueAsNumber: field.type === "number",
                  setValueAs: (value) =>
                    field.type === "number" ? Number(value) : value,
                })}
              />
              {form.formState.errors[field.name as keyof typeof form.formState.errors] && (
                <p className="text-sm text-red-500">
                  {(
                    form.formState.errors[field.name as keyof typeof form.formState.errors] as {
                      message: string;
                    }
                  ).message}
                </p>
              )}
            </div>
          ))}

          <div className="space-y-2">
            <Label htmlFor="would_recommend">Would Recommend</Label>
            <Input
              id="would_recommend"
              type="checkbox"
              {...form.register("would_recommend", {
                setValueAs: (value) => Boolean(value),
              })}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="comments">Comments</Label>
            <Textarea id="comments" {...form.register("comments")} />
          </div>
        </CardContent>
      </Card>

      <div className="flex gap-3 justify-end">
        {onCancel && (
          <Button type="button" variant="outline" onClick={onCancel}>
            Cancel
          </Button>
        )}
        <Button type="submit" disabled={isLoading}>
          {isLoading ? "Saving..." : "Save"}
        </Button>
      </div>
    </form>
  );
}

